CREATE TABLE community_relations(document TEXT NOT NULL REFERENCES documents(id) ON DELETE CASCADE,kind TEXT NOT NULL,actor TEXT NOT NULL,value JSONB NOT NULL,PRIMARY KEY(document,kind,actor));
CREATE INDEX community_relations_actor ON community_relations(actor,kind,document);
INSERT INTO community_relations SELECT id,'members',e.key,e.value FROM documents CROSS JOIN LATERAL jsonb_each(coalesce(body->'members','{}'::jsonb)) e;
INSERT INTO community_relations SELECT id,'applications',e.key,e.value FROM documents CROSS JOIN LATERAL jsonb_each(coalesce(body->'applications','{}'::jsonb)) e;
INSERT INTO community_relations SELECT id,'invitations',e.key,e.value FROM documents CROSS JOIN LATERAL jsonb_each(coalesce(body->'invitations','{}'::jsonb)) e;
INSERT INTO community_relations SELECT id,'participants',e.key,e.value FROM documents CROSS JOIN LATERAL jsonb_each(coalesce(body->'participants','{}'::jsonb)) e;
INSERT INTO community_relations SELECT id,'responses',e.key,e.value FROM documents CROSS JOIN LATERAL jsonb_each(coalesce(body->'responses','{}'::jsonb)) e;
INSERT INTO community_relations SELECT id,'votes',e.key,e.value FROM documents CROSS JOIN LATERAL jsonb_each(coalesce(body->'votes','{}'::jsonb)) e;
INSERT INTO community_relations SELECT id,'supporters',e.key,e.value FROM documents CROSS JOIN LATERAL jsonb_each(coalesce(body->'supporters','{}'::jsonb)) e;
INSERT INTO community_relations SELECT id,'reminded',e.key,e.value FROM documents CROSS JOIN LATERAL jsonb_each(coalesce(body->'reminded','{}'::jsonb)) e;
UPDATE documents SET body=body-ARRAY['members','applications','invitations','participants','responses','votes','supporters','reminded'];
CREATE VIEW community_documents AS SELECT d.id,d.section,d.sequence,d.body || jsonb_build_object('members',coalesce((SELECT jsonb_object_agg(actor,value) FROM community_relations WHERE document=d.id AND kind='members'),'{}'::jsonb),'applications',coalesce((SELECT jsonb_object_agg(actor,value) FROM community_relations WHERE document=d.id AND kind='applications'),'{}'::jsonb),'invitations',coalesce((SELECT jsonb_object_agg(actor,value) FROM community_relations WHERE document=d.id AND kind='invitations'),'{}'::jsonb),'participants',coalesce((SELECT jsonb_object_agg(actor,value) FROM community_relations WHERE document=d.id AND kind='participants'),'{}'::jsonb),'responses',coalesce((SELECT jsonb_object_agg(actor,value) FROM community_relations WHERE document=d.id AND kind='responses'),'{}'::jsonb),'votes',coalesce((SELECT jsonb_object_agg(actor,value) FROM community_relations WHERE document=d.id AND kind='votes'),'{}'::jsonb),'supporters',coalesce((SELECT jsonb_object_agg(actor,value) FROM community_relations WHERE document=d.id AND kind='supporters'),'{}'::jsonb),'reminded',coalesce((SELECT jsonb_object_agg(actor,value) FROM community_relations WHERE document=d.id AND kind='reminded'),'{}'::jsonb)) AS body FROM documents d;
CREATE TABLE community_profile(player TEXT PRIMARY KEY,about TEXT NOT NULL DEFAULT '',interests TEXT NOT NULL DEFAULT '');
CREATE TABLE community_ignores(player TEXT NOT NULL,target TEXT NOT NULL,PRIMARY KEY(player,target));
CREATE TABLE community_event_preferences(event TEXT NOT NULL REFERENCES documents(id) ON DELETE CASCADE,player TEXT NOT NULL,minutes INTEGER NOT NULL CHECK(minutes IN(-1,0,5,15,60)),PRIMARY KEY(event,player));
CREATE TABLE community_group_items(id TEXT PRIMARY KEY,group_id TEXT NOT NULL REFERENCES documents(id) ON DELETE CASCADE,kind TEXT NOT NULL CHECK(kind IN('task','place')),body JSONB NOT NULL,revision BIGINT NOT NULL DEFAULT 1);
CREATE INDEX community_group_items_group ON community_group_items(group_id,kind);
